import React from 'react';

function UserList({ users }) {
  return (
    <div>
      <h2>Danh sách user</h2>
      <ul>
        {users && users.length > 0 ? (
          users.map(user => (
            <li key={user.id}>{user.name} - {user.email}</li>
          ))
        ) : (
          <li>Chưa có user nào</li>
        )}
      </ul>
    </div>
  );
}

export default UserList;
